// Bluetooth lab B7 Music.  uv run pio run -d labs/ble-lab-b7 -e ble-lab-b7 -t upload
// The board becomes a Bluetooth MIDI instrument. MIDI carries notes, not sound: GarageBand on a
// Mac/iPhone/iPad, any synth app on Android, or the ble-app Music tab in Chrome makes the sound
// (and can send it on to your JBL speaker). Play with the button, five touch wires, serial
// commands, a drum machine; notes played on the other side light the board's piano and LED.
//
// Wiring: the screen from lesson 03. Optional: the push button on GPIO 5 (does what BOOT does),
// and jumper wires on GPIO 1, 2, 6, 13, 14 as five touch keys (`touch on`). 13 and 14 are the
// RC522's RST/IRQ wires from the RFID track: unplug the reader first, or use the other three.
//
// Views: keys · sequencer · roll · link · log
//   keys, sequencer, roll: the button plays. click = next note (sequencer: next beat),
//   double-click = chord (sequencer: start/stop), hold = all notes off, hold 2 s = next view.
//   link, log: click = next view.
// Serial: help lists the commands. Shared code: kit/lib/ble-kit (midi_ble.h = the packet format).
#include "b7_views.h"
#include "ble_lab.h"
#include "midi_ble.h"
#include "midi_service.h"
#include "music.h"
#include "server_link.h"
#include "touch_pads.h"

namespace {

ble::ServerLink links;
b7::MidiService midiOut;
b7::Scheduler sched;
b7::Screen screen;
constexpr uint8_t kPadPins[5] = {1, 2, 6, 13, 14};
TouchPads<5> pads(kPadPins);
uint8_t padNote[5] = {};
int walk = 0;               // the button's position in the scale
uint32_t nextStepAt = 0;    // the drum machine's next sixteenth
uint32_t tuneEndsAt = 0, tuneStartedAt = 0;
uint32_t lastInAt = 0;      // last note from the synth side (LED)
uint32_t connectedAt = 0;   // to notice a new connection
bool warnedDeaf = false;
uint32_t holdSince = 0;
uint8_t holdPin = 0;

constexpr int kSeqView = 1, kLinkView = 3;

uint32_t beatMs() { return 60000u / uint32_t(screen.bpm); }

void note(uint8_t n, uint8_t vel, uint32_t lengthMs, uint32_t startIn = 0, int channel = -1) {
  const uint8_t ch = uint8_t(channel < 0 ? screen.channel : channel);
  const uint32_t at = millis() + startIn;
  sched.at(at, midi::noteOn(ch, n, vel, 0));
  sched.at(at + lengthMs, midi::noteOff(ch, n, 0));
}

void panic() {
  sched.clear();
  screen.seqOn = false;
  screen.tune = nullptr;
  const uint16_t ts = millis() & 0x1FFF;
  const midi::Msg off[2] = {midi::allNotesOff(uint8_t(screen.channel), ts), midi::allNotesOff(b7::kDrumChannel, ts)};
  midiOut.send(off, 2);
  memset(screen.outBits, 0, sizeof(screen.outBits));
  for (b7::RollNote &r : screen.roll)
    if (!r.incoming && !r.off) r.off = millis();
  BLE_NOTE(Info, "all notes off");
}

void chord() {
  const int count = b7::scaleInfo(screen.scale).count;
  const int root = walk % count;
  for (int k = 0; k < 3; k++) note(b7::degreeNote(screen.scale, screen.octave, root + k * 2), 96, 600);
  BLE_NOTE(Tx, "chord on degree %d", root + 1);
}

void stepNote() {
  const int count = b7::scaleInfo(screen.scale).count;
  walk = (walk + 1) % (count * 2);  // up two octaves, then start again
  note(b7::degreeNote(screen.scale, screen.octave, walk), 100, 300);
}

// Send everything that's due in one go: a run of notes leaves in as few packets as fit.
void flush() {
  midi::Msg due[24];
  const int n = sched.due(millis(), due, 24);
  if (!n) return;
  for (int i = 0; i < n; i++) {
    const midi::Msg &m = due[i];
    if (midi::isNoteOn(m)) screen.setNote(m.d1, false, true);
    else if (midi::isNoteOff(m)) screen.setNote(m.d1, false, false);
  }
  if (!midiOut.send(due, size_t(n)) && !warnedDeaf) {
    warnedDeaf = true;
    BLE_NOTE(Warn, "no synth listening: notes stay on the screen");
  }
}

// ---- Views ------------------------------------------------------------------------------------

void drawKeys(BleLab &, FrameBuffer &fb, float t) { b7v::keys(fb, screen, t); }
void drawSeq(BleLab &, FrameBuffer &fb, float t) { b7v::sequencer(fb, screen, t); }
void drawRoll(BleLab &, FrameBuffer &fb, float t) { b7v::roll(fb, screen, t); }
void drawLink(BleLab &lab, FrameBuffer &fb, float t) { b7v::link(fb, lab.state(), screen, t); }
void drawLog(BleLab &, FrameBuffer &fb, float) { bv::log(fb); }

const BleView kViews[] = {
    {"keys", drawKeys, "chord"},
    {"sequencer", drawSeq, "seq"},
    {"roll", drawRoll, "chord"},
    {"link", drawLink, nullptr},
    {"log", drawLog, nullptr},
};

// ---- Commands ---------------------------------------------------------------------------------

void cmdPlay(BleLab &lab, const String &arg, const String &) {
  if (arg.isEmpty()) return lab.warn("play <notes>: play C4 E4 G4 · a chord: C4+E4+G4 · a rest: -");
  uint32_t at = 0;
  int from = 0, count = 0;
  while (from < int(arg.length())) {
    int sp = arg.indexOf(' ', from);
    if (sp < 0) sp = arg.length();
    const String token = arg.substring(from, sp);
    from = sp + 1;
    if (token.isEmpty()) continue;
    if (token != "-") {
      int a = 0;
      while (a < int(token.length())) {
        int plus = token.indexOf('+', a);
        if (plus < 0) plus = token.length();
        const int n = midi::parseNote(token.substring(a, plus).c_str());
        if (n < 0) return lab.warn("'%s' is not a note: C4, F#3, Bb2 (middle C = C4)", token.substring(a, plus).c_str());
        note(uint8_t(n), 100, beatMs() * 9 / 10, at);
        count++;
        a = plus + 1;
      }
    }
    at += beatMs();
  }
  BLE_NOTE(Info, "playing %d notes at %d bpm", count, screen.bpm);
}

void cmdTune(BleLab &lab, const String &, const String &lower) {
  const b7::Tune *tune = b7::findTune(lower);
  if (!tune) return lab.warn("tune twinkle | ode | frere");
  const uint32_t eighth = beatMs() / 2;
  uint32_t at = 0;
  const uint8_t c = uint8_t((screen.octave + 1) * 12);
  for (int i = 0; i < tune->count; i++) {
    const b7::Step &st = tune->steps[i];
    if (st.note >= 0) note(uint8_t(c + st.note), 96, st.eighths * eighth * 9 / 10, at);
    at += st.eighths * eighth;
  }
  screen.tune = tune->name;
  tuneStartedAt = millis();
  tuneEndsAt = millis() + at;
  screen.tuneLen = tune->count;
  BLE_NOTE(Info, "tune %s: %d notes, %.1f s", tune->name, tune->count, at / 1000.0f);
}

void cmdSeq(BleLab &lab, const String &, const String &lower) {
  if (!lower.isEmpty() && lower != "on" && lower != "off") return lab.warn("seq | seq on | seq off");
  screen.seqOn = lower.isEmpty() ? !screen.seqOn : lower == "on";
  if (screen.seqOn && !screen.beat) screen.beat = b7::findBeat("rock");
  if (screen.seqOn) {
    screen.step = 0;
    nextStepAt = millis();
  } else {
    sched.clear(b7::kDrumChannel);
  }
  BLE_NOTE(Info, "drums %s: %s at %d bpm", screen.seqOn ? "on" : "off", screen.beat ? screen.beat->name : "no beat", screen.bpm);
}

void cmdBpm(BleLab &lab, const String &arg, const String &) {
  long n = 0;
  if (!BleLab::number(arg, 40, 220, n)) return lab.warn("bpm <40-220> (now %d)", screen.bpm);
  screen.bpm = int(n);
  BLE_NOTE(Info, "%d bpm: a sixteenth is %lu ms", screen.bpm, static_cast<unsigned long>(15000 / n));
}

void cmdBeat(BleLab &lab, const String &, const String &lower) {
  const b7::Beat *b = b7::findBeat(lower);
  if (!b) return lab.warn("beat rock | funk | house | boom");
  screen.beat = b;
  lab.showView("sequencer");
  BLE_NOTE(Info, "beat %s%s", b->name, screen.seqOn ? "" : " (seq on to start)");
}

void cmdOctave(BleLab &lab, const String &arg, const String &) {
  long n = 0;
  if (!BleLab::number(arg, 1, 7, n)) return lab.warn("octave <1-7> (now %d; 4 = middle C)", screen.octave);
  screen.octave = int(n);
}

void cmdChannel(BleLab &lab, const String &arg, const String &) {
  long n = 0;
  if (!BleLab::number(arg, 1, 16, n)) return lab.warn("channel <1-16> (now %d; 10 = drums)", screen.channel + 1);
  screen.channel = int(n - 1);
}

void cmdScale(BleLab &lab, const String &, const String &lower) {
  if (lower == "pent" || lower == "pentatonic") screen.scale = b7::Scale::Pentatonic;
  else if (lower == "minor") screen.scale = b7::Scale::Minor;
  else if (lower == "major") screen.scale = b7::Scale::Major;
  else if (lower == "blues") screen.scale = b7::Scale::Blues;
  else return lab.warn("scale pent | minor | major | blues   (the button walks it)");
  walk = 0;
  BLE_NOTE(Info, "scale %s", b7::scaleInfo(screen.scale).name);
}

void cmdChord(BleLab &, const String &, const String &) { chord(); }
void cmdStop(BleLab &, const String &, const String &) { panic(); }

void cmdTouch(BleLab &lab, const String &, const String &lower) {
  if (lower != "on" && lower != "off") return lab.warn("touch on | touch off   (wires on GPIO 1 2 6 13 14, hands off while it measures)");
  pads.enable(lower == "on");
  screen.touchOn = pads.on();
  if (pads.on()) BLE_NOTE(Good, "touch on: 5 keys, pentatonic from C%d", screen.octave);
  else BLE_NOTE(Info, "touch off");
}

const BleCommand kCommands[] = {
    {"play", "<notes>", "play C4 E4 G4 · chords C4+E4+G4 · rest -", cmdPlay},
    {"tune", "<name>", "twinkle, ode, frere", cmdTune},
    {"seq", "[on|off]", "the drum machine (channel 10)", cmdSeq},
    {"beat", "<name>", "rock, funk, house, boom", cmdBeat},
    {"bpm", "<n>", "tempo, 40-220 (default 100)", cmdBpm},
    {"scale", "<name>", "pent, minor, major, blues: what the button walks", cmdScale},
    {"octave", "<n>", "1-7, 4 = middle C", cmdOctave},
    {"channel", "<n>", "MIDI channel 1-16 (10 = drums)", cmdChannel},
    {"chord", "", "a triad on the current note", cmdChord},
    {"stop", "", "all notes off, drums and tune stop", cmdStop},
    {"touch", "on|off", "five touch wires as keys", cmdTouch},
};

// ---- Hooks ------------------------------------------------------------------------------------

void setup(BleLab &lab) {
  // Macs and iPhones may ask to pair a MIDI device: allow it, Just Works with Secure Connections.
  NimBLEDevice::setSecurityAuth(true, false, true);
  NimBLEServer *server = NimBLEDevice::createServer();
  server->setCallbacks(&links, false);
  midiOut.begin(server);
  server->start();
  midiOut.advertise(lab.spec().deviceName);
}

void tick(BleLab &lab) {
  const uint32_t now = millis();
  const ble::LinkState ls = ble::link().get();
  // A new connection: ask for a short interval, 7.5-15 ms. MIDI wants low latency.
  if (ls.radio == ble::Radio::Connected && ls.connectedAt != connectedAt) {
    connectedAt = ls.connectedAt;
    warnedDeaf = false;
    NimBLEDevice::getServer()->updateConnParams(ls.peer.handle, 6, 12, 0, 200);
    BLE_NOTE(Tx, "asked for a 7.5-15 ms interval (low latency)");
  }

  // The drum machine: one sixteenth per step.
  if (screen.seqOn && screen.beat && int32_t(now - nextStepAt) >= 0) {
    for (int r = 0; r < 4; r++)
      if ((screen.beat->rows[r] >> screen.step) & 1)
        note(b7::kDrumNotes[r], r == 2 ? 70 : 110, 60, 0, b7::kDrumChannel);
    screen.step = (screen.step + 1) % 16;
    nextStepAt += 15000u / uint32_t(screen.bpm);
    if (int32_t(now - nextStepAt) > 200) nextStepAt = now;  // fell behind: don't burst
  }
  if (screen.tune && int32_t(now - tuneEndsAt) > 0) screen.tune = nullptr;

  // Touch keys: down = note on, up = note off. A firmer touch raises the reading more: velocity.
  uint32_t released = 0;
  const uint32_t pressed = pads.poll(released);
  for (int i = 0; i < 5; i++) {
    screen.padDown[i] = pads.on() && pads.down(i);
    screen.padRise[i] = pads.rise(i);
    if ((pressed >> i) & 1) {
      padNote[i] = b7::degreeNote(b7::Scale::Pentatonic, screen.octave, i);
      const uint8_t vel = uint8_t(constrain(50 + pads.rise(i), 50, 127));
      sched.at(now, midi::noteOn(uint8_t(screen.channel), padNote[i], vel, 0));
    }
    if ((released >> i) & 1) sched.at(now, midi::noteOff(uint8_t(screen.channel), padNote[i], 0));
  }

  flush();

  // What the other side plays: the piano strip, the roll, and the LED in the note's colour.
  midi::Msg in[16];
  const int n = midiOut.drain(in, 16);
  for (int i = 0; i < n; i++) {
    const midi::Msg &m = in[i];
    if (midi::isNoteOn(m)) {
      screen.setNote(m.d1, true, true);
      lab.claimLed(true);
      const uint16_t c = hsv(uint8_t((m.d1 % 12) * 21), 255, 255);
      const uint8_t level = uint8_t(m.d2 * 2);
      rgbLedWrite(PIN_RGB, uint8_t(((c >> 11) << 3) * level / 255), uint8_t((((c >> 5) & 63) << 2) * level / 255),
                  uint8_t(((c & 31) << 3) * level / 255));
      lastInAt = now;
      char nm[6];
      midi::noteName(m.d1, nm, sizeof(nm));
      BLE_NOTE(Rx, "note %s vel %u ch %u", nm, m.d2, (m.status & 15) + 1);
    } else if (midi::isNoteOff(m)) {
      screen.setNote(m.d1, true, false);
    } else if ((m.status & 0xF0) == 0xB0 && m.d1 == 123) {
      memset(screen.inBits, 0, sizeof(screen.inBits));
    }
  }
  if (lastInAt && now - lastInAt > 1500) {
    lastInAt = 0;
    lab.claimLed(false);
  }
  screen.stats = midiOut.stats();

  // A hold in a playing view: released before 2 s = all notes off, still held = next view.
  if (holdSince) {
    if (digitalRead(holdPin) == HIGH) {
      holdSince = 0;
      panic();
    } else if (now - holdSince >= 1400) {
      holdSince = 0;
      lab.setView(lab.view() + 1);
    }
  }
}

bool gesture(BleLab &lab, Gesture g, bool external) {
  const int v = lab.view();
  if (v >= kLinkView) return false;  // link and log: the usual click = next view
  switch (g) {
    case Gesture::Click:
      if (v == kSeqView) {
        static const char *const order[] = {"rock", "funk", "house", "boom"};
        int i = 0;
        while (i < 4 && screen.beat && strcmp(screen.beat->name, order[i]) != 0) i++;
        screen.beat = b7::findBeat(order[(i + 1) % 4]);
        BLE_NOTE(Info, "beat %s", screen.beat->name);
      } else {
        stepNote();
      }
      return true;
    case Gesture::LongPress:
      holdSince = millis();
      holdPin = external ? PIN_BUTTON : PIN_BOOT_BTN;
      return true;
    case Gesture::DoubleClick: return false;  // the view's action: chord, or seq on/off
  }
  return false;
}

const BleLabSpec kSpec{
    "ble-lab-b7", "B7", "Music", "Bench B7", kViews, sizeof(kViews) / sizeof(kViews[0]), 0,
    kCommands, sizeof(kCommands) / sizeof(kCommands[0]), setup, tick, gesture, nullptr,
};

BleLab lab(kSpec);

}  // namespace

void setup() { lab.begin(); }

void loop() { lab.loop(); }

// B7's screens (320 x 170):
//   keys       the five touch keys (or the button's next notes), a two-octave piano strip with
//              every note sounding right now: ours in violet, the synth side's in blue
//   sequencer  the drum machine: 4 drums x 16 steps, the playhead walking at the tempo
//   roll       a piano roll of the last 6 seconds, both directions
//   link       why BLE-MIDI is "almost live": notes wait for the next connection event
//   log        the activity log
#pragma once

#include "ble_views.h"
#include "midi_ble.h"
#include "midi_service.h"
#include "music.h"

namespace b7 {

struct RollNote {
  uint8_t note = 0;
  bool incoming = false;
  uint32_t on = 0, off = 0;  // off 0 = still sounding
};

struct Screen {
  Scale scale = Scale::Pentatonic;
  int octave = 4;
  int channel = 0;  // 0-15 (shown as 1-16)
  int bpm = 100;
  bool seqOn = false;
  const Beat *beat = nullptr;
  int step = 0;
  bool touchOn = false;
  bool padDown[5] = {};
  int padRise[5] = {};
  uint32_t outBits[4] = {}, inBits[4] = {};  // 128 notes each: sounding now
  const char *tune = nullptr;
  int tunePos = 0, tuneLen = 0;
  RollNote roll[48];
  int rollHead = 0;
  uint32_t presses[8] = {};  // millis() of our last note-ons, for the link view
  int pressHead = 0;
  Stats stats;

  bool out(uint8_t n) const { return (outBits[n >> 5] >> (n & 31)) & 1; }
  bool in(uint8_t n) const { return (inBits[n >> 5] >> (n & 31)) & 1; }
  void setNote(uint8_t n, bool incoming, bool on) {
    uint32_t *bits = incoming ? inBits : outBits;
    if (on) bits[n >> 5] |= 1u << (n & 31);
    else bits[n >> 5] &= ~(1u << (n & 31));
    if (on) {
      roll[rollHead++ % 48] = {n, incoming, millis(), 0};
      if (!incoming) presses[pressHead++ % 8] = millis();
    } else {
      for (int i = 0; i < 48; i++)
        if (roll[i].note == n && roll[i].incoming == incoming && roll[i].off == 0 && roll[i].on) roll[i].off = millis();
    }
  }
};

}  // namespace b7

namespace b7v {

using namespace bv;

constexpr uint16_t kOut = kViolet, kIn = kBlue;

// A piano strip: white keys then black keys on top. Lit by what's sounding.
inline void piano(FrameBuffer &fb, const b7::Screen &s, int x, int y, int lowNote, int octaves) {
  static const int whiteSteps[7] = {0, 2, 4, 5, 7, 9, 11};
  static const int blackSteps[5] = {1, 3, 6, 8, 10};
  static const int blackAfter[5] = {0, 1, 3, 4, 5};  // which white key a black key sits after
  const int ww = 13, wh = 34;
  for (int o = 0; o < octaves; o++)
    for (int w = 0; w < 7; w++) {
      const uint8_t n = uint8_t(lowNote + o * 12 + whiteSteps[w]);
      const int kx = x + (o * 7 + w) * ww;
      fb.fillRect(kx, y, ww - 1, wh, s.out(n) ? kOut : s.in(n) ? kIn : pal::ink);
      if (whiteSteps[w] == 0) {
        char nm[6];
        midi::noteName(n, nm, sizeof(nm));
        small(fb, kx + 1, y + wh - 9, pal::night, nm);
      }
    }
  for (int o = 0; o < octaves; o++)
    for (int b = 0; b < 5; b++) {
      const uint8_t n = uint8_t(lowNote + o * 12 + blackSteps[b]);
      const int kx = x + (o * 7 + blackAfter[b]) * ww + ww - 4;
      fb.fillRect(kx, y, 8, wh * 3 / 5, s.out(n) ? kOut : s.in(n) ? kIn : pal::night);
    }
}

inline void keys(FrameBuffer &fb, const b7::Screen &s, float t) {
  // Five pads, the notes of the pentatonic scale at the chosen octave.
  for (int i = 0; i < 5; i++) {
    const uint8_t n = b7::degreeNote(b7::Scale::Pentatonic, s.octave, i);
    const int x = 8 + i * 62, y = 34;
    const bool on = s.padDown[i] || s.out(n);
    fb.fillRoundRect(x, y, 56, 40, 5, on ? kOut : kPanel);
    fb.drawRoundRect(x, y, 56, 40, 5, s.touchOn ? pal::muted : pal::dim);
    char nm[6];
    midi::noteName(n, nm, sizeof(nm));
    bold(fb, x + 8, y + 22, on ? pal::ink : pal::muted, nm);
    static const uint8_t pins[5] = {1, 2, 6, 13, 14};
    char lbl[10];
    snprintf(lbl, sizeof(lbl), "GPIO %u", pins[i]);
    small(fb, x + 6, y + 30, pal::dim, lbl);
    if (s.touchOn) fb.fillRect(x + 4, y + 36, constrain(s.padRise[i], 0, 100) * 48 / 100, 2, pal::amber);
  }
  piano(fb, s, 22, 82, (s.octave) * 12, 2);
  char v[64];
  snprintf(v, sizeof(v), "%s, octave %d, ch %d%s%s", b7::scaleInfo(s.scale).name, s.octave, s.channel + 1, s.touchOn ? ", touch on" : "",
           s.tune ? ", playing" : "");
  small(fb, 8, 122, pal::muted, v);
  fb.fillRect(8, 136, 8, 6, kOut);
  small(fb, 20, 135, pal::muted, "this board");
  fb.fillRect(90, 136, 8, 6, kIn);
  small(fb, 102, 135, pal::muted, "from the synth");
  small(fb, 196, 135, s.stats.subscribed ? pal::teal : pal::amber, s.stats.subscribed ? "synth listening" : "no synth yet");
  (void)t;
}

inline void sequencer(FrameBuffer &fb, const b7::Screen &s, float t) {
  const uint16_t *rows = s.beat ? s.beat->rows : nullptr;
  for (int r = 0; r < 4; r++) {
    const int y = 38 + r * 22;
    small(fb, 6, y + 6, pal::muted, b7::kDrumNames[r]);
    for (int st = 0; st < 16; st++) {
      const int x = 44 + st * 17;
      const bool hit = rows && ((rows[r] >> st) & 1);
      const bool head = s.seqOn && st == s.step;
      uint16_t c = hit ? (head ? pal::amber : kOut) : (st % 4 == 0 ? pal::dim : kPanel);
      fb.fillRoundRect(x, y, 15, 18, 2, c);
      if (head) fb.drawRoundRect(x - 1, y - 1, 17, 20, 3, pal::ink);
    }
  }
  char v[64];
  snprintf(v, sizeof(v), "%s, %d bpm, %s, channel 10 (drums)", s.beat ? s.beat->name : "no beat", s.bpm, s.seqOn ? "playing" : "stopped");
  small(fb, 6, 130, s.seqOn ? pal::ink : pal::muted, v);
  small(fb, 6, 142, pal::dim, "beat rock|funk|house|boom, seq on|off, bpm <n>");
  (void)t;
}

inline void roll(FrameBuffer &fb, const b7::Screen &s, float t) {
  const uint32_t now = millis(), span = 6000;
  const int x0 = 6, x1 = 314, y0 = 34, y1 = 150;
  // Pitch lines every C.
  for (int n = 36; n <= 96; n += 12) {
    const int y = y1 - (n - 36) * (y1 - y0) / 60;
    fb.drawFastHLine(x0, y, x1 - x0, pal::dim);
    char nm[6];
    midi::noteName(uint8_t(n), nm, sizeof(nm));
    small(fb, x0, y - 9, pal::dim, nm);
  }
  for (const b7::RollNote &r : s.roll) {
    if (!r.on || now - r.on > span + 2000) continue;
    const uint32_t end = r.off ? r.off : now;
    if (now - end > span) continue;
    const int xa = x1 - int(int64_t(now - r.on) * (x1 - x0) / span), xb = x1 - int(int64_t(now - end) * (x1 - x0) / span);
    const int n = constrain(int(r.note), 36, 96);
    const int y = y1 - (n - 36) * (y1 - y0) / 60;
    fb.fillRect(std::max(xa, x0), y - 2, std::max(xb - std::max(xa, x0), 2), 4, r.incoming ? kIn : kOut);
  }
  fb.drawFastVLine(x1, y0, y1 - y0, pal::muted);
  char v[64];
  snprintf(v, sizeof(v), "out %lu msgs in %lu packets, in %lu, up to %u per packet", static_cast<unsigned long>(s.stats.msgsOut),
           static_cast<unsigned long>(s.stats.packetsOut), static_cast<unsigned long>(s.stats.msgsIn), s.stats.mostPerPacket);
  small(fb, 6, 152, pal::muted, v);
  (void)t;
}

// Connection events tick at the interval. A note pressed between two of them waits for the next:
// that wait (0 to one interval) is BLE-MIDI's latency. The timestamps inside the packet tell the
// synth when each note really happened, so a fast run of notes keeps its rhythm.
inline void link(FrameBuffer &fb, const ble::LinkState &ls, const b7::Screen &s, float t) {
  const bool up = ls.radio == ble::Radio::Connected;
  char v[64];
  const float interval = up ? ls.peer.interval * 1.25f : 15.0f;
  snprintf(v, sizeof(v), "%.2f ms", interval);
  stat(fb, 6, 34, up ? "connection interval" : "interval (not connected)", v, up ? kBlue : pal::muted);
  snprintf(v, sizeof(v), "0 - %.1f ms", interval);
  stat(fb, 130, 34, "added wait", v, pal::amber);
  snprintf(v, sizeof(v), "%u B", ls.peer.mtu);
  stat(fb, 250, 34, "MTU", up ? v : "-");
  // The timeline: 160 ms drawn across the screen. Ticks = connection events, one per interval.
  // Four presses at fixed moments, lit one after the other: each drops to the next tick.
  const int x0 = 6, x1 = 314, yNote = 88, yRadio = 120;
  const float window = 160.0f;
  auto xAt = [&](float ms) { return x0 + int(ms * (x1 - x0) / window); };
  small(fb, x0, yNote - 16, kOut, "you press");
  small(fb, x0, yRadio + 6, kBlue, "the radio sends");
  fb.drawFastHLine(x0, yRadio, x1 - x0, pal::dim);
  for (float e = 0; e <= window; e += interval) fb.drawFastVLine(xAt(e), yRadio - 4, 8, kBlue);
  const float presses[4] = {12, 49, 93, 131};
  const int lit = int(t * 1.2f) % 4;
  for (int i = 0; i < 4; i++) {
    const float sent = ceilf(presses[i] / interval) * interval;
    const int px = xAt(presses[i]), sx = xAt(sent);
    const bool on = i == lit;
    fb.fillCircle(px, yNote, on ? 4 : 2, on ? kOut : pal::dim);
    if (!on) continue;
    const float m = std::min(1.0f, fmodf(t * 1.2f, 1.0f) * 2);
    fb.drawLine(px, yNote, px + int((sx - px) * m), yNote + int((yRadio - yNote) * m), pal::amber);
    fb.drawFastHLine(px, yNote + 7, std::max(sx - px, 1), pal::amber);
    char w[24];
    snprintf(w, sizeof(w), "+%.1f ms", sent - presses[i]);
    small(fb, std::min(px, x1 - 50), yNote - 8, pal::amber, w);
  }
  snprintf(v, sizeof(v), "%s, %lu notes sent, timestamps keep the rhythm", up ? (ls.peer.encrypted ? "encrypted" : "plain") : "advertising",
           static_cast<unsigned long>(s.stats.msgsOut));
  small(fb, 6, 146, pal::muted, v);
}

}  // namespace b7v

// The standard BLE-MIDI service: one characteristic, both directions.
//
//   MIDI service         03B80E5A-EDE8-4B33-A751-6CE34EC4C700
//     MIDI I/O           7772E5DB-3868-4112-A1A9-F2669D106BF3   read, write without response, notify
//
// Notes we play go out as notifications; notes the other side plays (GarageBand's keyboard, the
// ble-app piano) come in as writes. Because it's the standard service, macOS, iOS, Android apps
// and Chrome's Web MIDI all treat the board as a MIDI keyboard: no app of ours needed.
#pragma once

#include <Arduino.h>
#include <NimBLEDevice.h>

#include "ble_link.h"
#include "midi_ble.h"
#include "server_link.h"

namespace b7 {

constexpr const char *kMidiService = "03B80E5A-EDE8-4B33-A751-6CE34EC4C700";
constexpr const char *kMidiChr = "7772E5DB-3868-4112-A1A9-F2669D106BF3";

struct Stats {
  uint32_t packetsIn = 0, msgsIn = 0, packetsOut = 0, msgsOut = 0;
  uint8_t mostPerPacket = 0;  // messages in one notification: the radio batches what fits
  bool subscribed = false;
};

class MidiService : public NimBLECharacteristicCallbacks {
 public:
  void begin(NimBLEServer *server) {
    NimBLEService *svc = server->createService(kMidiService);
    chr_ = svc->createCharacteristic(kMidiChr, NIMBLE_PROPERTY::READ | NIMBLE_PROPERTY::WRITE_NR | NIMBLE_PROPERTY::NOTIFY, 64);
    chr_->setValue(static_cast<const uint8_t *>(nullptr), 0);  // a read returns an empty packet (spec)
    chr_->setCallbacks(this);
  }

  // The 128-bit service UUID in the advertisement: that's what GarageBand and Audio MIDI Setup
  // look for. The name goes in the scan response.
  void advertise(const char *name) {
    NimBLEAdvertising *adv = NimBLEDevice::getAdvertising();
    NimBLEAdvertisementData data, response;
    data.setFlags(BLE_HS_ADV_F_DISC_GEN | BLE_HS_ADV_F_BREDR_UNSUP);
    data.addServiceUUID(NimBLEUUID(kMidiService));
    response.setName(name);
    adv->setAdvertisementData(data);
    adv->setScanResponseData(response);
    if (adv->start()) {
      ble::link().edit([](ble::LinkState &s) { s.radio = ble::Radio::Advertising, s.advertising = true; });
      BLE_NOTE(Info, "advertising as MIDI instrument \"%s\"", name);
    }
  }

  // From loop(): send messages, as few notifications as possible. Returns false if nobody listens.
  bool send(const midi::Msg *m, size_t n) {
    if (!stats().subscribed) return false;
    const ble::LinkState s = ble::link().get();
    const size_t cap = std::min<size_t>(s.peer.mtu > 3 ? s.peer.mtu - 3 : 20, sizeof(buf_));
    while (n) {
      size_t done = 0;
      const size_t len = midi::encode(m, n, buf_, cap, true, &done);
      if (!len || !done) return false;
      chr_->setValue(buf_, len);
      chr_->notify();
      ble::countTx(len);
      portENTER_CRITICAL(&lock_);
      stats_.packetsOut++;
      stats_.msgsOut += done;
      stats_.mostPerPacket = std::max<uint8_t>(stats_.mostPerPacket, uint8_t(done));
      portEXIT_CRITICAL(&lock_);
      m += done;
      n -= done;
    }
    return true;
  }

  // From loop(): what came in since the last call.
  int drain(midi::Msg *out, int max) {
    portENTER_CRITICAL(&lock_);
    int n = 0;
    while (n < max && head_ != tail_) out[n++] = inbox_[head_++ % kInbox];
    portEXIT_CRITICAL(&lock_);
    return n;
  }

  Stats stats() {
    portENTER_CRITICAL(&lock_);
    const Stats s = stats_;
    portEXIT_CRITICAL(&lock_);
    return s;
  }

  // ---- NimBLE task ----------------------------------------------------------------------------

  void onWrite(NimBLECharacteristic *c, NimBLEConnInfo &) override {
    const NimBLEAttValue v = c->getValue();
    midi::Msg msgs[16];
    const int n = decoder_.decode(v.data(), v.size(), msgs, 16);
    ble::countRx(v.size());
    if (n < 0) return BLE_NOTE(Warn, "not a BLE-MIDI packet (%u bytes)", v.size());
    portENTER_CRITICAL(&lock_);
    stats_.packetsIn++;
    stats_.msgsIn += n;
    for (int i = 0; i < n; i++)
      if (tail_ - head_ < uint32_t(kInbox)) inbox_[tail_++ % kInbox] = msgs[i];
    portEXIT_CRITICAL(&lock_);
  }

  void onSubscribe(NimBLECharacteristic *, NimBLEConnInfo &, uint16_t subValue) override {
    portENTER_CRITICAL(&lock_);
    stats_.subscribed = subValue != 0;
    portEXIT_CRITICAL(&lock_);
    if (subValue) BLE_NOTE(Good, "a synth is listening (subscribed)");
    else BLE_NOTE(Info, "the synth stopped listening");
  }

 private:
  static constexpr int kInbox = 64;
  NimBLECharacteristic *chr_ = nullptr;
  midi::Decoder decoder_;  // only used in the NimBLE task
  uint8_t buf_[64];
  portMUX_TYPE lock_ = portMUX_INITIALIZER_UNLOCKED;
  midi::Msg inbox_[kInbox];
  uint32_t head_ = 0, tail_ = 0;
  Stats stats_;
};

}  // namespace b7

// B7's little music engine: scales, three public-domain tunes, a 16-step drum machine, and a
// scheduler that turns "note at time t" into MIDI messages at the right moment.
//
// Nothing here makes sound. Every note becomes a MIDI message for the synth on the other side
// (GarageBand, the ble-app synth) and a line on the board's piano roll.
#pragma once

#include <Arduino.h>

#include "midi_ble.h"

namespace b7 {

// ---- Scales ------------------------------------------------------------------------------------

enum class Scale : uint8_t { Pentatonic, Minor, Major, Blues };

struct ScaleInfo {
  const char *name;
  uint8_t steps[7];
  uint8_t count;
};

inline const ScaleInfo &scaleInfo(Scale s) {
  // Semitones above the root. The major pentatonic has no "wrong" notes: any order sounds fine.
  static const ScaleInfo scales[] = {
      {"pentatonic", {0, 2, 4, 7, 9}, 5},
      {"minor pentatonic", {0, 3, 5, 7, 10}, 5},
      {"major", {0, 2, 4, 5, 7, 9, 11}, 7},
      {"blues", {0, 3, 5, 6, 7, 10}, 6},
  };
  return scales[static_cast<int>(s)];
}

// Degree 0, 1, 2 ... of the scale, climbing into higher octaves.
inline uint8_t degreeNote(Scale s, int octave, int degree) {
  const ScaleInfo &i = scaleInfo(s);
  const int note = (octave + 1) * 12 + (degree / i.count) * 12 + i.steps[degree % i.count];
  return uint8_t(constrain(note, 0, 127));
}

// ---- Tunes (public domain) ------------------------------------------------------------------------

struct Step {
  int8_t note;   // semitones from C of the chosen octave; -1 = rest
  uint8_t eighths;  // length in eighth notes
};

struct Tune {
  const char *name;
  const Step *steps;
  uint8_t count;
};

namespace tunes {
// Twinkle Twinkle Little Star
constexpr Step kTwinkle[] = {{0, 2}, {0, 2}, {7, 2}, {7, 2}, {9, 2}, {9, 2}, {7, 4}, {5, 2}, {5, 2}, {4, 2}, {4, 2}, {2, 2}, {2, 2}, {0, 4}};
// Ode to Joy (Beethoven)
constexpr Step kOde[] = {{4, 2}, {4, 2}, {5, 2}, {7, 2}, {7, 2}, {5, 2}, {4, 2}, {2, 2}, {0, 2}, {0, 2}, {2, 2}, {4, 2}, {4, 3}, {2, 1}, {2, 4}};
// Frere Jacques
constexpr Step kFrere[] = {{0, 2}, {2, 2}, {4, 2}, {0, 2}, {0, 2}, {2, 2}, {4, 2}, {0, 2}, {4, 2}, {5, 2}, {7, 4}, {4, 2}, {5, 2}, {7, 4}};
}  // namespace tunes

inline const Tune *findTune(const String &name) {
  static const Tune all[] = {{"twinkle", tunes::kTwinkle, sizeof(tunes::kTwinkle) / sizeof(Step)},
                             {"ode", tunes::kOde, sizeof(tunes::kOde) / sizeof(Step)},
                             {"frere", tunes::kFrere, sizeof(tunes::kFrere) / sizeof(Step)}};
  for (const Tune &t : all)
    if (name == t.name) return &t;
  return nullptr;
}

// ---- Drum machine ------------------------------------------------------------------------------

// General MIDI drums live on channel 10 (index 9): each note number is one drum.
constexpr uint8_t kDrumChannel = 9;
constexpr uint8_t kDrumNotes[4] = {36, 38, 42, 39};  // kick, snare, closed hi-hat, clap
constexpr const char *kDrumNames[4] = {"kick", "snare", "hat", "clap"};

struct Beat {
  const char *name;
  uint16_t rows[4];  // bit i = step i (of 16 sixteenth notes)
};

inline const Beat *findBeat(const String &name) {
  // Read the bits right to left: step 0 is bit 0.
  static const Beat beats[] = {
      {"rock", {0x0505, 0x1010, 0x5555, 0x0000}},
      {"funk", {0x2481, 0x9010, 0xFFFF, 0x0000}},
      {"house", {0x1111, 0x0000, 0x4444, 0x1010}},
      {"boom", {0x0281, 0x1010, 0x5555, 0x0000}},
  };
  for (const Beat &b : beats)
    if (name == b.name) return &b;
  return nullptr;
}

// ---- The scheduler -----------------------------------------------------------------------------

// Notes waiting for their moment: loop() asks for the due ones every frame and sends them in one go.
class Scheduler {
 public:
  bool at(uint32_t when, const midi::Msg &m) {
    if (count_ >= kMax) return false;
    q_[count_++] = {when, m};
    return true;
  }
  // Due messages into out (up to max), in time order. Stamps them with the send time.
  int due(uint32_t now, midi::Msg *out, int max) {
    int n = 0;
    while (n < max) {
      int best = -1;
      for (int i = 0; i < count_; i++)
        if (int32_t(now - q_[i].when) >= 0 && (best < 0 || int32_t(q_[i].when - q_[best].when) < 0)) best = i;
      if (best < 0) break;
      out[n] = q_[best].m;
      out[n].ts = uint16_t(now & 0x1FFF);
      n++;
      q_[best] = q_[--count_];
    }
    return n;
  }
  // Drop everything still waiting on a channel (or every channel, -1).
  void clear(int channel = -1) {
    for (int i = 0; i < count_;)
      if (channel < 0 || (q_[i].m.status & 15) == channel) q_[i] = q_[--count_];
      else i++;
  }
  int size() const { return count_; }

 private:
  static constexpr int kMax = 96;
  struct Item {
    uint32_t when;
    midi::Msg m;
  };
  Item q_[kMax];
  int count_ = 0;
};

}  // namespace b7

// The shell every Bluetooth LE lab (B1-B8) shares: the screen with its status bar, the push button
// and BOOT, the on-board LED, serial commands, and printing the activity log.
//
// A lab is a BleLabSpec: its views (each one a draw function, plus what a double-click does there),
// its serial commands, and three hooks: setup() once NimBLE is running, tick() on every loop, and
// gesture() to give the button a lab-specific meaning. Each src/ble-lab-bN/main.cpp is that list.
//
// Button or BOOT, by default: click = next view · double-click = this view's action · long press =
// the lab's long action. While a numeric comparison waits: click = yes, long press = no.
// On-board LED, unless the lab claims it: breathing blue = advertising · cyan pulse = scanning ·
// steady blue = connected · violet = encrypted · amber blink = a passkey waits · white blink = data.
#pragma once

#include <Arduino.h>
#include <NimBLEDevice.h>

#include "ble_link.h"
#include "ble_views.h"
#include "button.h"
#include "display.h"
#include "pins.h"

class BleLab;

enum class Gesture : uint8_t { Click, DoubleClick, LongPress };

struct BleCommand {
  const char *name;  // the first word you type
  const char *args;  // for help, e.g. "<dBm>"
  const char *what;  // one line for help
  void (*run)(BleLab &lab, const String &arg, const String &lower);
};

struct BleView {
  const char *name;  // "radar"
  void (*draw)(BleLab &lab, FrameBuffer &fb, float t);
  const char *action;  // the command line a double-click runs on this view, or nullptr
};

struct BleLabSpec {
  const char *env;         // "ble-lab-b1"
  const char *id;          // "B1"
  const char *title;       // "Listen"
  const char *deviceName;  // what phones see: "Bench B3"
  const BleView *views;
  int viewCount;
  int startView;
  const BleCommand *commands;
  int commandCount;
  void (*setup)(BleLab &lab) = nullptr;  // after NimBLE is initialised
  void (*tick)(BleLab &lab) = nullptr;   // every loop, before drawing
  // First say on every gesture. Return true when handled, false for the default.
  bool (*gesture)(BleLab &lab, Gesture g, bool external) = nullptr;
  const char *longAction = nullptr;  // the command line a long press runs by default
};

class BleLab {
 public:
  explicit BleLab(const BleLabSpec &spec) : spec_(spec), view_(spec.startView) {}

  void begin() {
    Serial.begin(115200);
    delay(1500);
    if (!display_.begin()) {
      log_e("No memory for the frame buffer. Stopping.");
      return;
    }
    rgbLedWrite(PIN_RGB, 0, 0, 0);
    external_.begin();
    boot_.begin();
    if (!NimBLEDevice::init(spec_.deviceName)) {
      log_e("NimBLE did not start. Stopping.");
      return;
    }
    Serial.printf("\n%s: NimBLE %s up, address %s, TX power %d dBm\n", spec_.env, NimBLEDevice::getVersion(),
                  NimBLEDevice::getAddress().toString().c_str(), NimBLEDevice::getPower());
    if (spec_.setup) spec_.setup(*this);
    printHelp();
  }

  void loop() {
    FrameBuffer &fb = display_.fb();
    if (fb.pixels() == nullptr) {
      delay(1000);
      return;
    }
    pollSerial();
    handleButton(external_, true);
    handleButton(boot_, false);
    measureRssi();
    if (spec_.tick) spec_.tick(*this);
    link_ = ble::link().get();
    printActivity();
    showLed();

    const float t = millis() / 1000.0f;
    const BleView &v = spec_.views[view_];
    fb.fillScreen(pal::night);
    v.draw(*this, fb, t);
    if (passkeyShowing()) bv::passkey(fb, link_, t);
    bv::header(fb, spec_.id, v.name, view_, spec_.viewCount, link_, t);
    char hint[40];
    if (passkeyShowing() && link_.passkeyCompare) snprintf(hint, sizeof(hint), "click = yes, long = no");
    else if (v.action) snprintf(hint, sizeof(hint), "2x: %s", v.action);
    else snprintf(hint, sizeof(hint), "click: next view");
    bv::footer(fb, hint);
    display_.push();
  }

  // ---- For views and commands ------------------------------------------------------------------

  const ble::LinkState &state() const { return link_; }
  const BleLabSpec &spec() const { return spec_; }
  int view() const { return view_; }

  void setView(int v) {
    view_ = (v % spec_.viewCount + spec_.viewCount) % spec_.viewCount;
    log_i("view %d: %s", view_ + 1, spec_.views[view_].name);
  }
  void showView(const char *name) {
    for (int i = 0; i < spec_.viewCount; i++)
      if (strcmp(spec_.views[i].name, name) == 0) return setView(i);
  }

  // The lab drives the on-board LED itself (B3's LED characteristic); false hands it back.
  void claimLed(bool claimed) {
    ledClaimed_ = claimed;
    ledShown_ = 0xFFFFFFFF;
  }

  // log_w is a macro that can't be returned from a void function; this can.
  [[gnu::format(printf, 2, 3)]] void warn(const char *fmt, ...) {
    char text[120];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(text, sizeof(text), fmt, ap);
    va_end(ap);
    log_w("%s", text);
  }

  // Parse a number argument; false when it is missing, not a number or out of range.
  static bool number(const String &arg, long lo, long hi, long &out) {
    if (arg.isEmpty()) return false;
    for (size_t i = 0; i < arg.length(); i++)
      if (!isDigit(arg[i]) && !(i == 0 && arg[i] == '-')) return false;
    out = arg.toInt();
    return out >= lo && out <= hi;
  }

  void runLine(const String &raw) {
    String line = raw;
    line.trim();
    if (line.isEmpty()) return;
    const int sp = line.indexOf(' ');
    String cmd = sp < 0 ? line : line.substring(0, sp);
    String arg = sp < 0 ? String() : line.substring(sp + 1);
    cmd.toLowerCase();
    arg.trim();
    String lower = arg;
    lower.toLowerCase();
    if (cmd == "help" || cmd == "?") return printHelp();
    if (cmd == "view") {
      long n = 0;
      if (!number(arg, 1, spec_.viewCount, n)) return warn("view <1-%d>", spec_.viewCount);
      return setView(n - 1);
    }
    if (cmd == "status") return printStatus();
    if (cmd == "power") return power(arg);
    for (int i = 0; i < spec_.commandCount; i++)
      if (cmd == spec_.commands[i].name) return spec_.commands[i].run(*this, arg, lower);
    log_w("unknown command '%s' in %s (type help)", line.c_str(), spec_.env);
  }

 private:
  bool passkeyShowing() const { return link_.passkey != 0 && millis() - link_.passkeySince < 30000; }

  void printHelp() {
    Serial.printf("\nBluetooth lab %s %s  (%s)  ·  phones see \"%s\"\n", spec_.id, spec_.title, spec_.env, spec_.deviceName);
    for (int i = 0; i < spec_.commandCount; i++) {
      const BleCommand &c = spec_.commands[i];
      char usage[40];
      snprintf(usage, sizeof(usage), "%s %s", c.name, c.args);
      Serial.printf("  %-28s %s\n", usage, c.what);
    }
    Serial.printf("  %-28s %s\n", "status", "the radio, the link and its security, in detail");
    Serial.printf("  %-28s %s\n", "power <dBm>", "transmit power: -24 to 20 (default 9)");
    Serial.printf("  %-28s %s\n", "view <n>", "show screen view n");
    Serial.print("Views:");
    for (int i = 0; i < spec_.viewCount; i++)
      Serial.printf(" %d %s%s", i + 1, spec_.views[i].name, i + 1 < spec_.viewCount ? " ·" : "\n");
    Serial.println("Button (GPIO 5, optional) or BOOT: click = next view, double-click = the view's action");
  }

  void printStatus() {
    const ble::LinkState s = ble::link().get();
    Serial.printf("radio %s · this board %s · TX power %d dBm\n", ble::radioName(s.radio), NimBLEDevice::getAddress().toString().c_str(),
                  NimBLEDevice::getPower());
    if (s.radio != ble::Radio::Connected) {
      if (s.lastDisconnect >= 0) Serial.printf("last link ended: 0x%02X %s\n", s.lastDisconnect & 0xFF, ble::disconnectReason(s.lastDisconnect));
      return;
    }
    const ble::Peer &p = s.peer;
    Serial.printf("peer %s%s%s (%s) · we are the %s\n", p.addr, p.idAddr[0] ? " id " : "", p.idAddr, p.name[0] ? p.name : "no name",
                  p.central ? "peripheral" : "central");
    Serial.printf("interval %.2f ms · latency %u · timeout %u ms · MTU %u · PHY %u/%u · RSSI %d dBm\n", p.interval * 1.25f, p.latency,
                  p.timeout * 10, p.mtu, p.txPhy, p.rxPhy, p.rssi);
    Serial.printf("security: %s, %s, %s, key %u bytes\n", p.encrypted ? "encrypted" : "not encrypted",
                  p.authenticated ? "authenticated (MITM)" : "not authenticated", p.bonded ? "bonded" : "not bonded", p.keySize);
    Serial.printf("traffic: rx %lu ops / %lu B · tx %lu ops / %lu B\n", static_cast<unsigned long>(s.rxOps), static_cast<unsigned long>(s.rxBytes),
                  static_cast<unsigned long>(s.txOps), static_cast<unsigned long>(s.txBytes));
  }

  void power(const String &arg) {
    long dbm = 0;
    if (!number(arg, -24, 20, dbm)) return warn("power <dBm>, -24 to 20. Now %d dBm", NimBLEDevice::getPower());
    if (!NimBLEDevice::setPower(int8_t(dbm))) return warn("the radio refused %ld dBm", dbm);
    BLE_NOTE(Info, "TX power %d dBm", NimBLEDevice::getPower());
  }

  void pollSerial() {
    static String buffer;
    while (Serial.available()) {
      const char c = Serial.read();
      if (c == '\n' || c == '\r') {
        if (!buffer.isEmpty()) runLine(buffer);
        buffer = "";
      } else if (c == 0x08 || c == 0x7F) {
        if (!buffer.isEmpty()) buffer.remove(buffer.length() - 1);
      } else if (uint8_t(c) < 0x20) {
        // Other control characters (arrow keys send escape sequences): ignore.
      } else if (buffer.length() < 120) {
        buffer += c;
      }
    }
  }

  void handleButton(Button &b, bool external) {
    Gesture g;
    switch (b.poll()) {
      case Button::Event::Click: g = Gesture::Click; break;
      case Button::Event::DoubleClick: g = Gesture::DoubleClick; break;
      case Button::Event::LongPress: g = Gesture::LongPress; break;
      default: return;
    }
    if (spec_.gesture && spec_.gesture(*this, g, external)) return;
    switch (g) {
      case Gesture::Click: setView(view_ + 1); break;
      case Gesture::DoubleClick:
        if (spec_.views[view_].action) {
          Serial.printf("> %s   (double-click)\n", spec_.views[view_].action);
          runLine(spec_.views[view_].action);
        }
        break;
      case Gesture::LongPress:
        if (spec_.longAction) {
          Serial.printf("> %s   (long press)\n", spec_.longAction);
          runLine(spec_.longAction);
        }
        break;
    }
  }

  // RSSI of a live link: the controller measures it on every connection event; we ask once a second.
  void measureRssi() {
    const ble::LinkState &s = link_;
    if (s.radio != ble::Radio::Connected || millis() - rssiAt_ < 1000) return;
    rssiAt_ = millis();
    int8_t rssi = 0;
    if (ble_gap_conn_rssi(s.peer.handle, &rssi) == 0) ble::link().edit([&](ble::LinkState &st) { st.peer.rssi = rssi; });
  }

  // New activity lines go to serial from here, in order, never from the NimBLE task.
  void printActivity() {
    ble::Activity &a = ble::activity();
    const uint32_t head = a.head();
    if (printed_ + ble::Activity::kSize < head) {
      Serial.printf("  ... %lu lines skipped\n", static_cast<unsigned long>(head - ble::Activity::kSize - printed_));
      printed_ = head - ble::Activity::kSize;
    }
    ble::ActEntry e;
    for (; printed_ < head; printed_++)
      if (a.get(printed_, e)) Serial.printf("  %s %s\n", bv::actMark(e.kind), e.text);
  }

  void showLed() {
    if (ledClaimed_) return;
    const uint32_t now = millis();
    const uint32_t traffic = link_.rxOps + link_.txOps;
    if (traffic != traffic_) traffic_ = traffic, flashUntil_ = now + 60;
    // Brightness in 12 steps, so the LED (a whole WS2812 frame per write) is only rewritten on a change.
    const float wave = 0.5f + 0.5f * sinf(now / 1000.0f * 3.1416f);
    const uint8_t breathe = uint8_t(int(wave * 11) * 8 + 6);
    uint8_t r = 0, g = 0, b = 0;
    if (passkeyShowing()) r = (now / 250) & 1 ? 120 : 0, g = r / 2;
    else if (now < flashUntil_) r = 120, g = 120, b = 120;
    else switch (link_.radio) {
      case ble::Radio::Off: break;
      case ble::Radio::Scanning: g = breathe / 2, b = breathe / 2; break;
      case ble::Radio::Advertising: b = breathe; break;
      case ble::Radio::Connecting: r = 60, g = 40; break;
      case ble::Radio::Connected:
        if (link_.peer.encrypted) r = 50, b = 90;
        else b = 90;
        break;
    }
    const uint32_t colour = (uint32_t(r) << 16) | (uint32_t(g) << 8) | b;
    if (colour == ledShown_) return;
    ledShown_ = colour;
    rgbLedWrite(PIN_RGB, r, g, b);
  }

  const BleLabSpec &spec_;
  Display display_;
  Button external_{PIN_BUTTON, "button"};
  Button boot_{PIN_BOOT_BTN, "BOOT"};
  ble::LinkState link_;
  int view_;
  bool ledClaimed_ = false;
  uint32_t ledShown_ = 0xFFFFFFFF, flashUntil_ = 0, traffic_ = 0, rssiAt_ = 0, printed_ = 0;
};

// MIDI over Bluetooth LE, the packet format. No Arduino and no radio here, so
// kit/test/host/ble_midi_test.cpp checks it on the Mac.
//
// Plain MIDI is a stream of 1-3 byte messages: status (what, which channel), then data
// (90 3C 64 = note on, channel 1, middle C, velocity 100). BLE-MIDI wraps them in one
// characteristic write or notification per connection event, with millisecond timestamps so
// the receiver can play them with the original timing even though the radio delivers in bursts:
//
//   [header][ts][status][data..] [ts][status][data..] [ts][data..] ...
//    1 0 hhhhhh   1 lllllll
//
// The header carries the top 6 bits of a 13-bit millisecond clock, each timestamp byte the low 7.
// When a low part is smaller than the one before it, the clock wrapped past 127: add 128.
// Running status: a message with the same status as the one before may leave its status byte
// out ([ts][data..]), and may even leave the timestamp out too ([data..], same time).
#pragma once

#include <stddef.h>
#include <stdint.h>

namespace midi {

struct Msg {
  uint8_t status = 0;  // 0x90 = note on, channel 1 (0x9F = channel 16)
  uint8_t d1 = 0, d2 = 0;
  uint16_t ts = 0;     // 13-bit milliseconds, wraps every 8.192 s
};

inline Msg noteOn(uint8_t ch, uint8_t note, uint8_t vel, uint16_t ts) { return {uint8_t(0x90 | (ch & 15)), uint8_t(note & 127), uint8_t(vel & 127), uint16_t(ts & 0x1FFF)}; }
inline Msg noteOff(uint8_t ch, uint8_t note, uint16_t ts) { return {uint8_t(0x80 | (ch & 15)), uint8_t(note & 127), 0, uint16_t(ts & 0x1FFF)}; }
// "All notes off" is a control change: CC 123 on the channel.
inline Msg allNotesOff(uint8_t ch, uint16_t ts) { return {uint8_t(0xB0 | (ch & 15)), 123, 0, uint16_t(ts & 0x1FFF)}; }

inline bool isNoteOn(const Msg &m) { return (m.status & 0xF0) == 0x90 && m.d2 > 0; }
// Many keyboards end a note with "note on, velocity 0" instead of a note off.
inline bool isNoteOff(const Msg &m) { return (m.status & 0xF0) == 0x80 || ((m.status & 0xF0) == 0x90 && m.d2 == 0); }

// How many data bytes follow a status byte. -1 = SysEx or undefined.
inline int dataBytes(uint8_t status) {
  if (status < 0x80) return -1;
  if (status < 0xF0) {
    const uint8_t kind = status & 0xF0;
    return kind == 0xC0 || kind == 0xD0 ? 1 : 2;  // program change, channel pressure: 1
  }
  switch (status) {
    case 0xF1: case 0xF3: return 1;
    case 0xF2: return 2;
    case 0xF6: return 0;
    default: return status >= 0xF8 ? 0 : -1;  // real-time: 0, F0/F4/F5/F7: no
  }
}

// ---- Encode -----------------------------------------------------------------------------------

// Pack messages into one packet. Timestamps must not go backwards. The receiver only notices a
// wrap of the low 7 bits, so a gap of more than 127 ms between two messages can't be told apart
// from a short one: we stop there and the next packet carries the rest with a fresh header.
// *encoded = messages packed. Returns the packet length (0 if not even the first fits).
inline size_t encode(const Msg *m, size_t n, uint8_t *out, size_t cap, bool runningStatus, size_t *encoded) {
  size_t len = 0, done = 0;
  uint8_t last = 0;
  uint16_t prevTs = 0;
  for (; done < n; done++) {
    const Msg &x = m[done];
    const int data = dataBytes(x.status);
    if (data < 0) break;  // no SysEx through here
    if (done == 0) {
      if (cap < 1) break;
      out[len++] = uint8_t(0x80 | ((x.ts >> 7) & 0x3F));
    } else if (uint16_t((x.ts - prevTs) & 0x1FFF) > 127) {
      break;  // the next packet carries it, with a fresh header
    }
    const bool skipStatus = runningStatus && x.status == last && x.status < 0xF0;
    const size_t need = 1 + (skipStatus ? 0 : 1) + size_t(data);
    if (len + need > cap) break;
    out[len++] = uint8_t(0x80 | (x.ts & 0x7F));
    if (!skipStatus) out[len++] = x.status;
    if (data >= 1) out[len++] = x.d1 & 0x7F;
    if (data >= 2) out[len++] = x.d2 & 0x7F;
    if (x.status < 0xF0) last = x.status;
    else if (x.status < 0xF8) last = 0;  // system common cancels running status
    prevTs = x.ts;
  }
  if (encoded) *encoded = done;
  return done ? len : 0;
}

// ---- Decode -----------------------------------------------------------------------------------

// Keeps running status and "inside a SysEx" between packets: a long SysEx spans several.
struct Decoder {
  uint8_t running = 0;
  bool sysex = false;
  uint32_t sysexSkipped = 0;  // bytes thrown away, for the curious

  // Up to max messages into out. Returns how many, or -1 for a packet without a header.
  int decode(const uint8_t *p, size_t n, Msg *out, int max) {
    if (n < 1 || (p[0] & 0xC0) != 0x80) return -1;
    uint8_t hi = p[0] & 0x3F;
    int lastLow = -1;
    uint16_t ts = uint16_t(hi << 7);
    int count = 0;
    size_t i = 1;
    auto stamp = [&](uint8_t b) {
      const int low = b & 0x7F;
      if (lastLow >= 0 && low < lastLow) hi = uint8_t((hi + 1) & 0x3F);
      lastLow = low;
      ts = uint16_t((hi << 7) | low);
    };
    auto emit = [&](uint8_t status, uint8_t d1, uint8_t d2) {
      if (count < max) out[count++] = Msg{status, d1, d2, ts};
    };
    while (i < n) {
      uint8_t b = p[i];
      if (sysex) {
        // Inside a SysEx every data byte is skipped. A byte with the top bit set is a timestamp,
        // followed by F7 (the end) or a real-time message squeezed in between.
        if ((b & 0x80) && i + 1 < n && (p[i + 1] == 0xF7 || p[i + 1] >= 0xF8)) {
          stamp(b);
          if (p[i + 1] == 0xF7) sysex = false;
          else emit(p[i + 1], 0, 0);
          i += 2;
        } else {
          sysexSkipped++;
          i++;
        }
        continue;
      }
      uint8_t status;
      if (b & 0x80) {
        stamp(b);  // a timestamp byte
        if (++i >= n) break;
        b = p[i];
        if (b & 0x80) {
          if (b == 0xF0) {
            sysex = true;
            running = 0;
            i++;
            continue;
          }
          if (b >= 0xF8) {  // real-time: one byte, leaves running status alone
            emit(b, 0, 0);
            i++;
            continue;
          }
          status = b;
          running = b < 0xF0 ? b : 0;
          i++;
        } else {
          status = running;  // [ts][data..]
        }
      } else {
        status = running;  // [data..]: running status, same time
      }
      const int data = dataBytes(status);
      if (status == 0 || data < 0) {  // data with nothing to belong to: skip it
        i++;
        continue;
      }
      if (i + size_t(data) > n) break;  // cut off
      uint8_t d[2] = {0, 0};
      bool bad = false;
      for (int k = 0; k < data; k++) {
        d[k] = p[i + k];
        if (d[k] & 0x80) bad = true;
      }
      if (bad) break;  // a status byte where data should be: give up on this packet
      emit(status, d[0], d[1]);
      i += size_t(data);
    }
    return count;
  }
};

// ---- Names ------------------------------------------------------------------------------------

// 60 -> "C4" (MIDI note 60 is middle C, octave 4).
inline void noteName(uint8_t note, char *out, size_t n) {
  static const char *const names[] = {"C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"};
  if (n < 5) return;
  const int octave = note / 12 - 1;
  const char *nm = names[note % 12];
  size_t i = 0;
  while (*nm && i + 1 < n) out[i++] = *nm++;
  if (octave < 0 && i + 1 < n) out[i++] = '-';
  if (i + 1 < n) out[i++] = char('0' + (octave < 0 ? -octave : octave));
  out[i] = 0;
}

// "C4", "f#3", "Bb2" -> MIDI note; -1 if it isn't one.
inline int parseNote(const char *s) {
  static const int base[] = {9, 11, 0, 2, 4, 5, 7};  // a b c d e f g
  char c = s[0];
  if (c >= 'a' && c <= 'g') c = char(c - 'a' + 'A');
  if (c < 'A' || c > 'G') return -1;
  int note = base[c - 'A'];
  int i = 1;
  if (s[i] == '#') note++, i++;
  else if (s[i] == 'b') note--, i++;
  bool neg = false;
  if (s[i] == '-') neg = true, i++;
  if (s[i] < '0' || s[i] > '9' || s[i + 1] != 0) return -1;
  const int octave = neg ? -(s[i] - '0') : s[i] - '0';
  const int midi = (octave + 1) * 12 + note;
  return midi >= 0 && midi <= 127 ? midi : -1;
}

}  // namespace midi

// The peripheral side of a link (B3-B7): NimBLE's server callbacks, turned into ble::link() state
// and activity lines. Labs make one, hand it to the server, and override what they need.
//
// Pairing hooks are here too, because every lab after B3 meets them: a passkey to show, a number
// to compare. The passkey goes into the link state; the shell draws it over any view, and the
// button (click = yes, long press = no) or serial `yes`/`no` answers through confirm().
#pragma once

#include <Arduino.h>
#include <NimBLEDevice.h>
#include <esp_random.h>

#include "ble_link.h"

namespace ble {

inline void fillPeer(Peer &p, const NimBLEConnInfo &c) {
  strlcpy(p.addr, c.getAddress().toString().c_str(), sizeof(p.addr));
  const NimBLEAddress id = c.getIdAddress();
  if (!(id == c.getAddress())) strlcpy(p.idAddr, id.toString().c_str(), sizeof(p.idAddr));
  else p.idAddr[0] = 0;
  p.addrType = c.getAddress().getType();
  p.handle = c.getConnHandle();
  p.mtu = c.getMTU();
  p.interval = c.getConnInterval();
  p.latency = c.getConnLatency();
  p.timeout = c.getConnTimeout();
  p.encrypted = c.isEncrypted();
  p.authenticated = c.isAuthenticated();
  p.bonded = c.isBonded();
  p.keySize = c.getSecKeySize();
  p.central = c.isSlave();  // we are the slave (peripheral), so the peer is the central
}

class ServerLink : public NimBLEServerCallbacks {
 public:
  // Advertising starts again by itself after a disconnect (NimBLE's advertiseOnDisconnect).
  void onConnect(NimBLEServer *, NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) {
      s.peer = Peer{};
      fillPeer(s.peer, c);
      s.radio = Radio::Connected;
      s.advertising = false;
      s.connections++;
      s.connectedAt = millis();
      s.rxOps = s.txOps = s.rxBytes = s.txBytes = 0;
    });
    BLE_NOTE(Good, "connected: %s", c.getAddress().toString().c_str());
    BLE_NOTE(Info, "interval %.2f ms, latency %u, timeout %u ms", c.getConnInterval() * 1.25f, c.getConnLatency(), c.getConnTimeout() * 10);
  }

  void onDisconnect(NimBLEServer *server, NimBLEConnInfo &c, int reason) override {
    link().edit([&](LinkState &s) {
      s.connections = s.connections ? s.connections - 1 : 0;
      s.radio = advertiseAgain_ ? Radio::Advertising : Radio::Off;
      s.advertising = advertiseAgain_;
      s.lastDisconnect = reason;
      s.passkey = 0;
    });
    BLE_NOTE(Warn, "disconnected 0x%02X: %s", reason & 0xFF, disconnectReason(reason));
    (void)server;
  }

  void onMTUChange(uint16_t mtu, NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) { s.peer.mtu = mtu; });
    BLE_NOTE(Info, "MTU %u: %u bytes of data per packet", mtu, mtu - 3);
    (void)c;
  }

  void onConnParamsUpdate(NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) { fillPeer(s.peer, c); });
    BLE_NOTE(Info, "new params: %.2f ms, latency %u", c.getConnInterval() * 1.25f, c.getConnLatency());
  }

  void onPhyUpdate(NimBLEConnInfo &c, uint8_t tx, uint8_t rx) override {
    link().edit([&](LinkState &s) { s.peer.txPhy = tx, s.peer.rxPhy = rx; });
    BLE_NOTE(Info, "PHY now %s / %s", tx == 2 ? "2M" : tx == 3 ? "Coded" : "1M", rx == 2 ? "2M" : rx == 3 ? "Coded" : "1M");
    (void)c;
  }

  // ---- Pairing -------------------------------------------------------------------------------

  // Passkey entry, we display: six random digits, the other side types them.
  uint32_t onPassKeyDisplay() override {
    const uint32_t key = esp_random() % 1000000;
    link().edit([&](LinkState &s) { s.passkey = key ? key : 1, s.passkeyCompare = false, s.passkeySince = millis(); });
    BLE_NOTE(Warn, "passkey %06lu: type it on the other device", static_cast<unsigned long>(key));
    return key;
  }

  // Numeric comparison: both screens show the same 6 digits; a person says yes on both.
  void onConfirmPassKey(NimBLEConnInfo &c, uint32_t pin) override {
    pendingHandle_ = c.getConnHandle();
    link().edit([&](LinkState &s) { s.passkey = pin ? pin : 1, s.passkeyCompare = true, s.passkeySince = millis(); });
    BLE_NOTE(Warn, "compare %06lu: same on the phone? (click/yes)", static_cast<unsigned long>(pin));
  }

  void onAuthenticationComplete(NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) {
      fillPeer(s.peer, c);
      s.passkey = 0;
    });
    if (c.isEncrypted())
      BLE_NOTE(Good, "secured: %s%s, key %u B", c.isAuthenticated() ? "authenticated" : "Just Works", c.isBonded() ? ", bonded" : "", c.getSecKeySize());
    else
      BLE_NOTE(Bad, "pairing failed: still plain text");
  }

  void onIdentity(NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) { fillPeer(s.peer, c); });
    BLE_NOTE(Info, "identity: %s", c.getIdAddress().toString().c_str());
  }

  // Answer a numeric comparison (button or serial). False when nothing is waiting.
  bool confirm(bool yes) {
    if (pendingHandle_ == 0xFFFF) return false;
    NimBLEServer *server = NimBLEDevice::getServer();
    if (server) NimBLEDevice::injectConfirmPasskey(server->getPeerInfoByHandle(pendingHandle_), yes);
    pendingHandle_ = 0xFFFF;
    link().edit([&](LinkState &s) { s.passkey = 0; });
    BLE_NOTE(Info, "you said %s", yes ? "yes, it matches" : "no");
    return true;
  }
  bool comparing() const { return pendingHandle_ != 0xFFFF; }

  void setAdvertiseAgain(bool on) { advertiseAgain_ = on; }

 private:
  uint16_t pendingHandle_ = 0xFFFF;
  bool advertiseAgain_ = true;
};

}  // namespace ble

// Jumper wires as touch keys: the ESP32-S3's capacitive touch sensor.
//
// GPIO 1-14 can measure how much charge their pin holds. A finger on a bare wire end adds
// capacitance, so the reading rises (on the S3 it goes UP when touched; on the original ESP32
// it went down). We measure each pad with nobody touching it (the baseline) when you switch
// touch on, then call it touched above +25 % and released below +15 %: the gap (hysteresis)
// stops a finger hovering at the edge from flickering on and off.
//
// Shared by B5-B7 (kit/lib/ble-kit). Nothing to wire beyond a jumper in the pin, the other end loose. Keep your hands off the wires
// while `touch on` measures the baselines.
#pragma once

#include <Arduino.h>

template <int N>
class TouchPads {
 public:
  explicit TouchPads(const uint8_t (&pins)[N]) {
    for (int i = 0; i < N; i++) pins_[i] = pins[i];
  }

  bool on() const { return on_; }
  uint8_t pin(int i) const { return pins_[i]; }
  uint32_t value(int i) const { return value_[i]; }
  uint32_t baseline(int i) const { return base_[i]; }
  bool down(int i) const { return (down_ >> i) & 1; }
  // How far above the baseline, in percent (for a bar on screen and a velocity).
  int rise(int i) const { return base_[i] ? int((int64_t(value_[i]) - base_[i]) * 100 / base_[i]) : 0; }

  // Switch on: measure every pad 8 times with nobody touching. Takes ~0.1 s.
  void enable(bool on) {
    on_ = on;
    down_ = 0;
    if (!on) return;
    for (int i = 0; i < N; i++) {
      uint64_t sum = 0;
      for (int k = 0; k < 8; k++) sum += touchRead(pins_[i]);
      base_[i] = uint32_t(sum / 8);
      value_[i] = base_[i];
    }
  }

  // Every ~40 ms from loop(). Returns the pads that went down (bit i) since the last call;
  // `released` gets the ones that came up.
  uint32_t poll(uint32_t &released) {
    released = 0;
    if (!on_ || millis() - at_ < 40) return 0;
    at_ = millis();
    uint32_t pressed = 0;
    for (int i = 0; i < N; i++) {
      value_[i] = touchRead(pins_[i]);
      const bool was = down(i);
      const uint64_t v = uint64_t(value_[i]) * 100;
      if (!was && v > uint64_t(base_[i]) * 125) down_ |= 1u << i, pressed |= 1u << i;
      else if (was && v < uint64_t(base_[i]) * 115) down_ &= ~(1u << i), released |= 1u << i;
    }
    return pressed;
  }

 private:
  uint8_t pins_[N];
  uint32_t base_[N] = {}, value_[N] = {};
  uint32_t down_ = 0, at_ = 0;
  bool on_ = false;
};

// Drawing pieces every BLE lab shares (320 x 170, landscape):
//   header   "BLE" + the view's name, view dots, and the status cluster: what the radio is doing,
//            a lock when the link is encrypted, a key when the peer is bonded, signal bars
//   footer   the button hint on the left, the latest activity line on the right
//   link     a live connection: who is central, the connection events ticking, MTU, PHY, security
//   log      the activity log, newest at the bottom
//   passkey  the big 6 digits, drawn over any view while pairing waits for you
#pragma once

#include <Fonts/FreeSans9pt7b.h>
#include <Fonts/FreeSansBold24pt7b.h>
#include <Fonts/FreeSansBold9pt7b.h>
#include <math.h>

#include "ble_link.h"
#include "color.h"
#include "frame_buffer.h"

namespace bv {

constexpr int kW = 320, kH = 170, kTop = 30, kBottom = kH - 12;
// Bluetooth's own colours on the bench palette: blue = radio, violet = encrypted.
constexpr uint16_t kBlue = rgb(80, 150, 255);
constexpr uint16_t kViolet = rgb(176, 130, 255);
constexpr uint16_t kPanel = rgb(20, 28, 40);

inline int textWidth(FrameBuffer &fb, const char *s) {
  int16_t x1, y1;
  uint16_t w, h;
  fb.getTextBounds(s, 0, 0, &x1, &y1, &w, &h);
  return w;
}

inline void small(FrameBuffer &fb, int x, int y, uint16_t c, const char *s) {
  fb.setFont(nullptr);
  fb.setTextColor(c);
  fb.setCursor(x, y);
  fb.print(s);
}

inline void bold(FrameBuffer &fb, int x, int y, uint16_t c, const char *s) {
  fb.setFont(&FreeSansBold9pt7b);
  fb.setTextColor(c);
  fb.setCursor(x, y);
  fb.print(s);
}

// A label over a value, in a column.
inline void stat(FrameBuffer &fb, int x, int y, const char *label, const char *value, uint16_t c = pal::ink) {
  small(fb, x, y, pal::muted, label);
  bold(fb, x, y + 22, c, value);
}

// Four bars, like a phone's: -50 dBm and up = 4 bars, -90 and below = 0.
inline void signalBars(FrameBuffer &fb, int x, int y, int rssi, uint16_t on = pal::ink) {
  const int bars = rssi == 0 ? 0 : rssi >= -55 ? 4 : rssi >= -67 ? 3 : rssi >= -78 ? 2 : rssi >= -90 ? 1 : 0;
  for (int i = 0; i < 4; i++) {
    const int h = 3 + i * 3;
    fb.fillRect(x + i * 4, y + 12 - h, 3, h, i < bars ? on : pal::dim);
  }
}

inline uint16_t rssiColour(int rssi) { return rssi >= -67 ? pal::teal : rssi >= -82 ? pal::amber : pal::coral; }

inline void lockIcon(FrameBuffer &fb, int x, int y, uint16_t c) {
  fb.drawRoundRect(x + 2, y, 7, 7, 3, c);
  fb.fillRect(x, y + 5, 11, 8, c);
}

inline void keyIcon(FrameBuffer &fb, int x, int y, uint16_t c) {
  fb.drawCircle(x + 3, y + 6, 3, c);
  fb.drawFastHLine(x + 6, y + 6, 7, c);
  fb.drawFastVLine(x + 11, y + 6, 4, c);
  fb.drawFastVLine(x + 9, y + 6, 3, c);
}

// The radio's state as a small animated glyph centred on (x, y).
inline void radioGlyph(FrameBuffer &fb, int x, int y, ble::Radio r, float t) {
  switch (r) {
    case ble::Radio::Off: fb.drawCircle(x, y, 5, pal::dim); break;
    case ble::Radio::Scanning: {
      // A radar sweep: we are listening.
      fb.drawCircle(x, y, 7, pal::dim);
      const float a = t * 5.0f;
      fb.drawLine(x, y, x + int(cosf(a) * 7), y + int(sinf(a) * 7), pal::teal);
      fb.fillCircle(x, y, 1, pal::teal);
      break;
    }
    case ble::Radio::Advertising: {
      // Rings leaving the antenna: we are shouting.
      fb.fillCircle(x, y, 2, kBlue);
      for (int i = 0; i < 2; i++) {
        const float k = fmodf(t * 1.2f + i * 0.5f, 1.0f);
        fb.drawCircle(x, y, 3 + int(k * 6), mix(kBlue, pal::night, uint8_t(k * 255)));
      }
      break;
    }
    case ble::Radio::Connecting:
      fb.drawCircle(x, y, 6, (int(t * 6) & 1) ? pal::amber : pal::dim);
      break;
    case ble::Radio::Connected:
      // Two linked rings: a connection.
      fb.drawCircle(x - 3, y, 4, kBlue);
      fb.drawCircle(x + 3, y, 4, kBlue);
      break;
  }
}

inline void header(FrameBuffer &fb, const char *labId, const char *view, int index, int count, const ble::LinkState &s, float t) {
  fb.setFont(&FreeSansBold9pt7b);
  fb.setTextColor(kBlue);
  fb.setCursor(8, 18);
  fb.print(labId);
  fb.print(" ");
  fb.setFont(&FreeSans9pt7b);
  fb.setTextColor(pal::muted);
  fb.print(view);
  // Status cluster, right to left: signal, key, lock, radio.
  int x = 302;
  if (s.radio == ble::Radio::Connected && s.peer.rssi != 0) signalBars(fb, x, 9, s.peer.rssi, rssiColour(s.peer.rssi));
  x -= 18;
  if (s.peer.bonded && s.radio == ble::Radio::Connected) keyIcon(fb, x, 8, pal::amber), x -= 18;
  if (s.peer.encrypted && s.radio == ble::Radio::Connected) lockIcon(fb, x + 2, 7, kViolet), x -= 16;
  radioGlyph(fb, x + 4, 15, s.radio, t);
  const int firstDot = x - 14 - (count - 1) * 9;
  for (int i = 0; i < count; i++) fb.fillCircle(firstDot + i * 9, 15, 3, i == index ? pal::ink : pal::dim);
  fb.drawFastHLine(0, 28, kW, pal::dim);
}

inline uint16_t actColour(ble::Act k) {
  switch (k) {
    case ble::Act::Good: return pal::teal;
    case ble::Act::Warn: return pal::amber;
    case ble::Act::Bad: return pal::coral;
    case ble::Act::Rx: return kBlue;
    case ble::Act::Tx: return kViolet;
    default: return pal::muted;
  }
}

inline const char *actMark(ble::Act k) {
  switch (k) {
    case ble::Act::Good: return "+";
    case ble::Act::Warn: return "!";
    case ble::Act::Bad: return "x";
    case ble::Act::Rx: return "<";
    case ble::Act::Tx: return ">";
    default: return "-";
  }
}

// Left: the button hint. Right: the newest activity line, fading after 6 s.
inline void footer(FrameBuffer &fb, const char *hint) {
  fb.fillRect(0, kH - 11, kW, 11, pal::night);
  small(fb, 6, kH - 9, pal::muted, hint);
  ble::Activity &a = ble::activity();
  ble::ActEntry e;
  const uint32_t head = a.head();
  if (head == 0 || !a.get(head - 1, e)) return;
  const uint32_t age = millis() - e.ms;
  if (age > 6000) return;
  char right[30];
  strlcpy(right, e.text, sizeof(right));
  fb.setFont(nullptr);
  const uint16_t c = mix(actColour(e.kind), pal::night, uint8_t(age > 4000 ? (age - 4000) * 200 / 2000 : 0));
  small(fb, kW - 6 - textWidth(fb, right), kH - 9, c, right);
}

// ---- log ----------------------------------------------------------------------------------------

inline void log(FrameBuffer &fb, int y0 = kTop + 4, int rows = 10) {
  ble::Activity &a = ble::activity();
  const uint32_t head = a.head();
  if (head == 0) {
    small(fb, 8, y0 + 4, pal::muted, "Nothing on the air yet.");
    return;
  }
  const uint32_t from = head > uint32_t(rows) ? head - rows : 0;
  ble::ActEntry e;
  int y = y0;
  for (uint32_t i = from; i < head; i++, y += 12) {
    if (!a.get(i, e)) continue;
    char when[12];
    snprintf(when, sizeof(when), "%5lu.%lu", static_cast<unsigned long>(e.ms / 1000), static_cast<unsigned long>(e.ms / 100 % 10));
    small(fb, 4, y, pal::dim, when);
    small(fb, 50, y, actColour(e.kind), actMark(e.kind));
    char text[44];
    strlcpy(text, e.text, sizeof(text));
    small(fb, 60, y, i + 1 == head ? pal::ink : pal::muted, text);
  }
}

// ---- link ---------------------------------------------------------------------------------------

// The connection drawn as two devices and the connection events between them: one exchange every
// interval, the dot's speed is real time slowed down 20x so 7.5-50 ms intervals stay visible.
inline void link(FrameBuffer &fb, const ble::LinkState &s, float t, const char *usLabel = "this board", const char *themLabel = nullptr) {
  const bool up = s.radio == ble::Radio::Connected;
  const int ly = 62, lx = 30, rx = 150;
  fb.fillRoundRect(lx - 22, ly - 22, 44, 44, 6, kPanel);
  fb.drawRoundRect(lx - 22, ly - 22, 44, 44, 6, kBlue);
  fb.fillRoundRect(rx - 16, ly - 26, 32, 52, 6, kPanel);
  fb.drawRoundRect(rx - 16, ly - 26, 32, 52, 6, up ? kBlue : pal::dim);
  small(fb, lx - 18, ly + 28, pal::muted, usLabel);
  small(fb, rx - 18, ly + 28, pal::muted, themLabel ? themLabel : (up && s.peer.name[0] ? s.peer.name : "peer"));
  // Who leads: the central sets the timing, the peripheral answers in each event.
  small(fb, lx - 18, ly - 4, pal::ink, s.peer.central || !up ? "periph" : "central");
  small(fb, rx - 14, ly - 4, up ? pal::ink : pal::dim, s.peer.central ? "central" : "periph");
  if (up) {
    const float intervalMs = s.peer.interval * 1.25f;
    const float period = fmaxf(intervalMs * 20.0f / 1000.0f, 0.15f);
    const float k = fmodf(t, period) / period;
    const int x = lx + 24 + int(k * (rx - lx - 42));
    fb.drawFastHLine(lx + 24, ly - 6, rx - lx - 42, pal::dim);
    fb.drawFastHLine(lx + 24, ly + 6, rx - lx - 42, pal::dim);
    fb.fillCircle(x, ly - 6, 3, s.peer.encrypted ? kViolet : kBlue);
    fb.fillCircle(lx + 24 + (rx - lx - 42) - (x - lx - 24), ly + 6, 3, pal::teal);
    if (s.peer.encrypted) lockIcon(fb, (lx + rx) / 2 - 5, ly - 26, kViolet);
  } else {
    small(fb, lx + 30, ly - 3, pal::muted, s.advertising ? "waiting..." : "no link");
  }

  char v[40];
  const int cx = 190;
  if (!up) {
    stat(fb, cx, 38, "last link ended", s.lastDisconnect < 0 ? "-" : "", pal::muted);
    if (s.lastDisconnect >= 0) {
      snprintf(v, sizeof(v), "reason 0x%02X", s.lastDisconnect & 0xFF);
      bold(fb, cx, 60, pal::ink, v);
      char why[34];
      strlcpy(why, ble::disconnectReason(s.lastDisconnect), sizeof(why));
      small(fb, cx, 68, pal::muted, why);
    }
    return;
  }
  snprintf(v, sizeof(v), "%.2f ms", s.peer.interval * 1.25f);
  stat(fb, cx, 34, "interval", v, kBlue);
  snprintf(v, sizeof(v), "%u B", s.peer.mtu);
  stat(fb, cx + 74, 34, "MTU", v);
  snprintf(v, sizeof(v), "%u", s.peer.latency);
  stat(fb, cx, 70, "latency", v);
  snprintf(v, sizeof(v), "%u ms", s.peer.timeout * 10);
  stat(fb, cx + 74, 70, "timeout", v);
  static const char *const phy[] = {"?", "1M", "2M", "Coded"};
  snprintf(v, sizeof(v), "%s/%s", phy[s.peer.txPhy & 3], phy[s.peer.rxPhy & 3]);
  stat(fb, cx, 106, "PHY tx/rx", v);
  snprintf(v, sizeof(v), "%d dBm", s.peer.rssi);
  stat(fb, cx + 74, 106, "RSSI", s.peer.rssi ? v : "-", s.peer.rssi ? rssiColour(s.peer.rssi) : pal::muted);
  // Security row under the drawing.
  const uint16_t sc = s.peer.encrypted ? kViolet : pal::muted;
  snprintf(v, sizeof(v), "%s%s%s", s.peer.encrypted ? "encrypted" : "plain text", s.peer.authenticated ? " + MITM" : "", s.peer.bonded ? " + bonded" : "");
  small(fb, 8, 114, sc, v);
  snprintf(v, sizeof(v), "%s  up %lus", s.peer.addr, static_cast<unsigned long>((millis() - s.connectedAt) / 1000));
  small(fb, 8, 126, pal::muted, v);
  snprintf(v, sizeof(v), "rx %lu ops %lu B", static_cast<unsigned long>(s.rxOps), static_cast<unsigned long>(s.rxBytes));
  small(fb, 8, 138, kBlue, v);
  snprintf(v, sizeof(v), "tx %lu ops %lu B", static_cast<unsigned long>(s.txOps), static_cast<unsigned long>(s.txBytes));
  small(fb, 8, 148, kViolet, v);
}

